            "name": "方案名称",
            "target": "目标人群",
            "focus": ["景点1", "景点2"],
            "characteristics": "方案特点",
            "estimated_satisfaction": 0.8
        }
    },
    "information_gaps": {
        "missing_inputs": ["缺失信息1"],
        "impact": "缺失影响"
    },
    "clarification_questions": ["问题1", "问题2"],
    "recommend_plan": {
        "themes": ["主题1", "主题2"],
        "num_plans": 3,
        "focus_points": ["侧重点1", "侧重点2"],
        "weights": {"budget": 0.3, "experience": 0.4, "convenience": 0.3}
    },
    "output": "推荐计划描述"
}

请制定推荐策略：

## 用户信息
- 目的地：{destination}
- 出发日：{dates}
- 周期：{duration}
- 预算：{budget}
- 偏好：{preferences}

## 搜索结果摘要
{search_results}

## 用户原始请求
{user_content}

返回 JSON 格式的推荐策略。

